package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.MathArrays;
import org.apache.commons.math3.util.Pair;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for {@link DiscreteDistribution#sample(int)}.
 */
public class DiscreteDistribution_sample_TriageGen5Test {

    private List<Pair<String, Double>> sampleData;
    private DiscreteDistribution<String> distribution;

    @Before
    public void setUp() {
        sampleData = new ArrayList<>();
        sampleData.add(new Pair<>("A", 0.5));
        sampleData.add(new Pair<>("B", 0.5));
        distribution = new DiscreteDistribution<>(sampleData);
    }

    @Test
    public void testSample_Success() {
        int sampleSize = 5;
        String[] result = distribution.sample(sampleSize);

        assertNotNull(result);
        assertEquals(sampleSize, result.length);
        for (String s : result) {
            assertNotNull(s);
        }
    }

    @Test
    public void testSample_ZeroSize_ThrowsException() {
        int sampleSize = 0;
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(sampleSize);
        });
    }

    @Test
    public void testSample_NegativeSize_ThrowsException() {
        int sampleSize = -1;
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(sampleSize);
        });
    }

    @Test
    public void testSample_LargeSize() {
        int sampleSize = 100;
        String[] result = distribution.sample(sampleSize);
        assertEquals(sampleSize, result.length);
    }

    @Test
    public void testSample_SingleElementDistribution() {
        List<Pair<Integer, Double>> singleData = new ArrayList<>();
        singleData.add(new Pair<>(1, 1.0));
        DiscreteDistribution<Integer> singleDist = new DiscreteDistribution<>(singleData);

        int sampleSize = 3;
        Integer[] result = singleDist.sample(sampleSize);

        assertEquals(sampleSize, result.length);
        for (Integer i : result) {
            assertEquals(Integer.valueOf(1), i);
        }
    }
}
